                rows.push(ComparisonRow {
                    key: copy.clone(),
                    name,
                    address,
                    blocking_keys: ids
                        .iter()
                        .flat_map(|id| blocking_keys(&self.observations[id]))
                        .collect::<BTreeSet<_>>()
                        .into_iter()
